function formatEmailFrom(from) {
  if (!from) return 'Unknown sender';
  if (typeof from === 'string') return from;
  if (from.text) return from.text;
  if (Array.isArray(from.value) && from.value[0]) {
    const v = from.value[0];
    if (v.name && v.address) return `${v.name} <${v.address}>`;
    return v.address || v.name || 'Unknown sender';
  }
  return 'Unknown sender';
}

function candidateFromFileName(fileName) {
  if (!fileName) return 'Unknown Candidate';
  return fileName
    .replace(/\.(pdf|docx?|PDF|DOCX?)$/,'')
    .replace(/[-_]+/g, ' ')
    .replace(/\bresume\b/gi, '')
    .replace(/\bcv\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim() || 'Unknown Candidate';
}

const items = [];

for (const item of $input.all()) {
  const binary = item.binary || {};
  const keys = Object.keys(binary);

  for (const key of keys) {
    if (!key.startsWith('attachment_')) continue;

    const file = binary[key];
    const lowerName = (file.fileName || key).toLowerCase();
    const mime = (file.mimeType || '').toLowerCase();

    const isResume =
      lowerName.endsWith('.pdf') ||
      lowerName.endsWith('.docx') ||
      lowerName.endsWith('.doc') ||
      mime.includes('pdf') ||
      mime.includes('word') ||
      mime.includes('document');

    if (!isResume) continue;

    const fileName = file.fileName || key;

    items.push({
      json: {
        emailSubject: item.json.subject || '(no subject)',
        emailFrom: formatEmailFrom(item.json.from || item.json.From),
        fileName,
        candidateName: candidateFromFileName(fileName),
      },
      binary: {
        data: file,
      },
    });
  }
}

return items;

const token = $('Login HireFlow').first().json.access_token;

if (!token) {
  throw new Error('Login failed — no access_token. Check email/password in Login HireFlow node.');
}

return $('Extract Resume Attachments').all().map((item) => ({
  json: {
    ...item.json,
    access_token: token,
  },
  binary: item.binary,
}));

const resume = $('Upload Resume').item.json;
const emailMeta = $('Attach Token + Resume').item.json;
const jobsRaw = $input.first().json;
const jobList = Array.isArray(jobsRaw) ? jobsRaw : [jobsRaw];

return jobList.map((job) => ({
  json: {
    resume_id: resume.id,
    job_id: job.id,
    job_title: job.title,
    company: job.company,
    fileName: emailMeta.fileName,
    emailSubject: emailMeta.emailSubject,
    emailFrom: emailMeta.emailFrom,
    candidateName: emailMeta.candidateName,
  },
}));

const prepared = $('Prepare Match Items').all();
const matches = $input.all();

return matches.map((item, i) => {
  const meta = prepared[i]?.json || {};
  const m = item.json;

  return {
    json: {
      resume_id: m.resume_id || meta.resume_id,
      job_id: m.job_id || meta.job_id,
      job_title: meta.job_title,
      company: meta.company,
      fileName: meta.fileName,
      emailFrom: meta.emailFrom,
      emailSubject: meta.emailSubject,
      candidateName: meta.candidateName,
      match_score: m.match_score,
      matched_skills: m.matched_skills || [],
      missing_skills: m.missing_skills || [],
      explanation: m.explanation || '',
    },
  };
});

function formatEmailFrom(from) {
  if (!from) return 'Unknown sender';
  if (typeof from === 'string') return from;
  if (from.text) return from.text;
  if (Array.isArray(from.value) && from.value[0]) {
    const v = from.value[0];
    if (v.name && v.address) return `${v.name} <${v.address}>`;
    return v.address || v.name || 'Unknown sender';
  }
  return 'Unknown sender';
}

function candidateFromFileName(fileName) {
  if (!fileName) return 'Unknown Candidate';
  return fileName
    .replace(/\.(pdf|docx?|PDF|DOCX?)$/,'')
    .replace(/[-_]+/g, ' ')
    .replace(/\bresume\b/gi, '')
    .replace(/\bcv\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim() || 'Unknown Candidate';
}

const rows = $input.all().map((i) => i.json);

if (rows.length === 0) {
  return [];
}

rows.sort((a, b) => (b.match_score || 0) - (a.match_score || 0));

const first = rows[0];
const candidateName = first.candidateName || candidateFromFileName(first.fileName);
const sender = formatEmailFrom(first.emailFrom);
const top = rows[0];
const others = rows.slice(1);

const topMatched = (top.matched_skills || []).slice(0, 10).join(', ') || 'N/A';
const topMissing = (top.missing_skills || []).slice(0, 8).join(', ') || 'None';

const otherLines = others.map((r, idx) => {
  return `${idx + 2}. *${r.job_title}* @ ${r.company} — *${r.match_score}%*`;
});

const text = [
  `<!channel>`,
  ``,
  `👋 *Dear HR Team,*`,
  ``,
  `A new candidate resume just landed in HireFlow and has been screened against our open roles.`,
  ``,
  `*Candidate:* ${candidateName}`,
  `*Resume file:* ${first.fileName || 'N/A'}`,
  `*Received from:* ${sender}`,
  `*Email subject:* ${first.emailSubject || '(no subject)'}`,
  `*Resume ID:* \`${first.resume_id}\``,
  ``,
  `*Best match*`,
  `• *${top.job_title}* @ ${top.company}`,
  `  Match score: *${top.match_score}%*`,
  `  Matched skills: ${topMatched}`,
  `  Missing skills: ${topMissing}`,
  top.explanation ? `  Summary: ${top.explanation}` : null,
  ``,
  others.length ? `*Other matches (score ≥ 50):*` : null,
  ...otherLines,
  ``,
  `_Please review this candidate and proceed with shortlisting if it looks like a fit._`,
].filter((line) => line !== null).join('\n');

return [{
  json: {
    text,
    count: rows.length,
    top_score: top.match_score,
    candidateName,
  },
}];
